package com.yesbee.nwtrack.workflow;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.yesbee.nwtrack.shared.BusinessRuleException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.*;

@Service
public class OperationsService {
    private final JdbcTemplate jdbc;private final ObjectMapper json;private final StationAccessService access;
    public OperationsService(JdbcTemplate jdbc,ObjectMapper json,StationAccessService access){this.jdbc=jdbc;this.json=json;this.access=access;}

    public Map<String,Object> resolveNfc(String uid){
        List<Map<String,Object>> rows=jdbc.queryForList("select n.id tag_id,n.uid,n.name tag_name,n.status tag_status,n.active assigned,n.asset_type,n.trolley_id,t.code trolley_code,a.lot_id,l.lot_number,sty.style_number,l.status lot_status,coalesce(n.station_id,p.station_id,m.station_id,sa.station_id,sl.station_id) station_id,st.code station_code,coalesce(n.process_id,m.process_id) process_id,coalesce(p.name,mp.name) process_name,coalesce(p.code,mp.code) process_code,n.machine_id,m.name machine_name,m.status machine_status,n.storage_area_id,sa.code storage_area_code,n.storage_location_id,sl.code storage_unit_code from nfc_tags n left join trolleys t on t.id=n.trolley_id left join lot_trolley_assignments a on a.trolley_id=t.id and a.released_at is null left join lots l on l.id=a.lot_id left join styles sty on sty.id=l.style_id left join processes p on p.id=n.process_id left join machines m on m.id=n.machine_id left join processes mp on mp.id=m.process_id left join storage_areas sa on sa.id=n.storage_area_id left join storage_locations sl on sl.id=n.storage_location_id left join stations st on st.id=coalesce(n.station_id,p.station_id,m.station_id,sa.station_id,sl.station_id) where n.uid=?",uid.trim().toUpperCase(Locale.ROOT));
        if(rows.isEmpty())throw new BusinessRuleException("UNKNOWN_NFC","NFC tag is not registered");
        Map<String,Object> result=rows.getFirst();
        if(!"ACTIVE".equals(result.get("tag_status")))throw new BusinessRuleException("NFC_RETIRED","NFC tag is deleted");
        if(!Boolean.TRUE.equals(result.get("assigned")))throw new BusinessRuleException("NFC_NOT_ASSIGNED","NFC tag is active but is not assigned to an asset");
        result.put("processId",result.get("process_id"));result.put("processName",result.get("process_name"));result.put("stationId",result.get("station_id"));result.put("stationNumber",result.get("station_code"));
        return result;
    }
    @Transactional public void linkTrolley(UUID lotId,UUID trolleyId,UUID actor){String lotStatus=jdbc.queryForObject("select status from lots where id=? for update",String.class,lotId);if(Set.of("COMPLETED","CANCELLED","IN_STORAGE").contains(lotStatus))throw new BusinessRuleException("TROLLEY_LINK_NOT_ALLOWED","Lot cannot be linked in its current state");Boolean active=jdbc.queryForObject("select active from trolleys where id=? for update",Boolean.class,trolleyId);if(!Boolean.TRUE.equals(active))throw new BusinessRuleException("TROLLEY_INACTIVE","Trolley is inactive");Integer occupied=jdbc.queryForObject("select count(*) from lot_trolley_assignments where trolley_id=? and released_at is null",Integer.class,trolleyId);if(occupied!=null&&occupied>0)throw new BusinessRuleException("TROLLEY_OCCUPIED","Trolley is already assigned");Integer assigned=jdbc.queryForObject("select count(*) from lot_trolley_assignments where lot_id=? and released_at is null",Integer.class,lotId);if(assigned!=null&&assigned>0)throw new BusinessRuleException("LOT_ALREADY_LINKED","Lot already has an active trolley");jdbc.update("insert into lot_trolley_assignments(id,lot_id,trolley_id,linked_by) values (?,?,?,?)",UUID.randomUUID(),lotId,trolleyId,actor);jdbc.update("update trolleys set status='IN_USE',version=version+1 where id=? and active",trolleyId);jdbc.update("update lots set current_location_type='TROLLEY',current_location_id=?,version=version+1 where id=?",trolleyId,lotId);location(lotId,"TROLLEY",trolleyId,actor);}

    @Transactional public Map<String,Object> dispatch(UUID lotId,UUID actor){LotRow lot=jdbc.queryForObject("select id,lot_number,status,current_route_sequence from lots where id=? for update",(rs,n)->new LotRow((UUID)rs.getObject(1),rs.getString(2),rs.getString(3),(Integer)rs.getObject(4)),lotId);if(lot==null)throw new BusinessRuleException("LOT_NOT_FOUND","Lot not found");Integer trolleyCount=jdbc.queryForObject("select count(*) from lot_trolley_assignments where lot_id=? and released_at is null",Integer.class,lotId);if(trolleyCount==null||trolleyCount==0)throw new BusinessRuleException("TROLLEY_REQUIRED","Link a trolley before Dispatch");int sequence=lot.currentSequence()==null?1:lot.currentSequence();if("READY_FOR_DISPATCH".equals(lot.status()))sequence++;Map<String,Object> visit=jdbc.queryForMap("select sv.id visit_id,sv.station_id,s.code station_code,s.name station_name,st.id style_id,st.style_number,l.quantity,t.id trolley_id,t.code trolley_code from station_visits sv join lot_route_entries lre on lre.id=sv.lot_route_entry_id join stations s on s.id=sv.station_id join lots l on l.id=sv.lot_id join styles st on st.id=l.style_id left join lot_trolley_assignments a on a.lot_id=l.id and a.released_at is null left join trolleys t on t.id=a.trolley_id where sv.lot_id=? and lre.sequence_no=?",lotId,sequence);UUID visitId=(UUID)visit.get("visit_id"),stationId=(UUID)visit.get("station_id");jdbc.update("update station_visits set status='DISPATCHED',dispatched_at=now(),version=version+1 where id=?",visitId);jdbc.update("update lot_route_entries set status='DISPATCHED' where lot_id=? and sequence_no=?",lotId,sequence);jdbc.update("update lots set status='DISPATCHED',current_route_sequence=?,version=version+1 where id=?",sequence,lotId);Map<String,Object> payload=new LinkedHashMap<>();payload.put("lotId",lotId);payload.put("lotNumber",lot.lotNumber());payload.put("lotStatus","DISPATCHED");payload.put("quantity",visit.get("quantity"));payload.put("styleId",visit.get("style_id"));payload.put("trolleyId",visit.get("trolley_id"));payload.put("trolleyCode",visit.get("trolley_code"));payload.put("routeSequence",sequence);payload.put("destinationStationName",visit.get("station_name"));payload.put("styleNumber",visit.get("style_number"));payload.put("destinationStationId",stationId);payload.put("destinationStation",visit.get("station_code"));payload.put("visitId",visitId);try{jdbc.update("insert into outbox_events(id,aggregate_type,aggregate_id,aggregate_version,event_type,payload) values (?,'LOT',?,1,'INCOMING_LOT',?::jsonb)",UUID.randomUUID(),lotId,json.writeValueAsString(payload));}catch(com.fasterxml.jackson.core.JsonProcessingException e){throw new IllegalStateException(e);}return payload;}

    @Transactional public void retrieveStorage(UUID storageId,UUID lotId,UUID trolleyId,UUID actor){UUID station=jdbc.queryForObject("select station_id from storage_locations where id=?",UUID.class,storageId);access.assertCanOperate(actor,station);List<Map<String,Object>> rows=jdbc.queryForList("select id,lot_id from storage_occupancies where storage_location_id=? and lot_id=? and retrieved_at is null for update",storageId,lotId);if(rows.isEmpty())throw new BusinessRuleException("STORAGE_OCCUPANCY_NOT_FOUND","Selected Lot is not actively stored in this Storage Unit");Boolean active=jdbc.queryForObject("select active from trolleys where id=? for update",Boolean.class,trolleyId);if(!Boolean.TRUE.equals(active))throw new BusinessRuleException("TROLLEY_INACTIVE","Trolley is inactive");Integer occupied=jdbc.queryForObject("select count(*) from lot_trolley_assignments where trolley_id=? and released_at is null",Integer.class,trolleyId);if(occupied!=null&&occupied>0)throw new BusinessRuleException("TROLLEY_OCCUPIED","Trolley is already assigned");UUID occupancyId=(UUID)rows.getFirst().get("id");jdbc.update("update storage_occupancies set retrieved_at=now(),retrieved_by=? where id=?",actor,occupancyId);jdbc.update("insert into lot_trolley_assignments(id,lot_id,trolley_id,linked_by) values (?,?,?,?)",UUID.randomUUID(),lotId,trolleyId,actor);jdbc.update("update trolleys set status='IN_USE',version=version+1 where id=? and active",trolleyId);jdbc.update("update lots set status='AT_STATION',current_location_type='TROLLEY',current_location_id=?,version=version+1 where id=?",trolleyId,lotId);location(lotId,"TROLLEY",trolleyId,actor);}

    @Transactional public String transition(UUID executionId,String target,String reason,UUID actor,boolean supervisor){return transition(executionId,target,reason,actor,supervisor,false);}
    @Transactional public String transition(UUID executionId,String target,String reason,UUID actor,boolean supervisor,boolean qualityCompletion){access.assertCanExecute(actor,executionId);if(jdbc.queryForObject("select count(*) from process_executions pe join station_visits sv on sv.id=pe.station_visit_id join lots l on l.id=sv.lot_id join lot_route_entries lr on lr.id=sv.lot_route_entry_id where pe.id=? and sv.status in ('RECEIVED','ACTIVE','READY_FOR_DISPATCH') and l.status not in ('COMPLETED','CANCELLED') and lr.sequence_no=l.current_route_sequence",Integer.class,executionId)!=1)throw new BusinessRuleException("PROCESS_NOT_AT_STATION","Receive the current lot visit before operating its processes");if(!qualityCompletion && Set.of("COMPLETED","SKIPPED").contains(target) && isFinalQuality(executionId))throw new BusinessRuleException("QC_RESULT_REQUIRED","Complete final quality with passedQuantity, rejectedQuantity and remarks");ExecRow row=jdbc.queryForObject("select pe.status,pe.station_visit_id,pe.sequence_no,sv.station_id from process_executions pe join station_visits sv on sv.id=pe.station_visit_id where pe.id=? for update",(rs,n)->new ExecRow(rs.getString(1),(UUID)rs.getObject(2),rs.getInt(3),(UUID)rs.getObject(4)),executionId);if(row==null)throw new BusinessRuleException("PROCESS_NOT_FOUND","Process execution not found");access.assertCanOperate(actor,row.stationId());if(!allowed(row.status(),target,supervisor))throw new BusinessRuleException("PROCESS_TRANSITION_INVALID","Cannot change Process from "+row.status()+" to "+target);if("IN_PROGRESS".equals(target)){Integer previous=jdbc.queryForObject("select count(*) from process_executions where station_visit_id=? and sequence_no<? and status not in ('COMPLETED','SKIPPED')",Integer.class,row.visitId(),row.sequence());if(previous!=null&&previous>0)throw new BusinessRuleException("PROCESS_ORDER_VIOLATION","Previous Processes must be resolved first");}jdbc.update("update process_executions set status=?,started_at=case when ?='IN_PROGRESS' and started_at is null then now() else started_at end,completed_at=case when ? in ('COMPLETED','SKIPPED') then now() else null end,operator_id=?,reason=?,version=version+1 where id=?",target,target,target,actor,reason,executionId);jdbc.update("insert into process_state_events(process_execution_id,from_status,to_status,actor_id,reason) values (?,?,?,?,?)",executionId,row.status(),target,actor,reason);if("IN_PROGRESS".equals(target))jdbc.update("update lots set status='IN_PROCESS',version=version+1 where id=(select lot_id from station_visits where id=?)",row.visitId());Integer remaining=jdbc.queryForObject("select count(*) from process_executions where station_visit_id=? and status not in ('COMPLETED','SKIPPED')",Integer.class,row.visitId());if(remaining!=null&&remaining==0){jdbc.update("update station_visits set status='READY_FOR_DISPATCH',version=version+1 where id=?",row.visitId());jdbc.update("update lots set status='READY_FOR_DISPATCH',version=version+1 where id=(select lot_id from station_visits where id=?)",row.visitId());}if(Set.of("COMPLETED","SKIPPED").contains(target)){List<UUID> used=jdbc.queryForList("select machine_id from process_machine_usage where process_execution_id=? and completed_at is null",UUID.class,executionId);jdbc.update("update process_machine_usage set completed_at=now(),completed_by=? where process_execution_id=? and completed_at is null",actor,executionId);for(UUID machine:used)jdbc.update("update machines set status=case when not active then 'INACTIVE' when status in ('DOWN','MAINTENANCE') then status else 'AVAILABLE' end,version=version+1 where id=?",machine);if(!qualityCompletion)closeOrdinaryLot(executionId,actor);}return target;}
    private void closeOrdinaryLot(UUID execution,UUID actor){
        UUID lot=jdbc.queryForObject("select sv.lot_id from process_executions pe join station_visits sv on sv.id=pe.station_visit_id where pe.id=?",UUID.class,execution);
        if(jdbc.queryForObject("select count(*) from process_executions pe join station_visits sv on sv.id=pe.station_visit_id where sv.lot_id=? and pe.status not in ('COMPLETED','SKIPPED')",Integer.class,lot)!=0)return;
        // A final quality execution cannot reach here without a result.
        jdbc.queryForObject("select id from lots where id=? for update",UUID.class,lot);
        jdbc.update("update station_visits set status='COMPLETED',completed_at=now(),version=version+1 where lot_id=?",lot);
        jdbc.update("update lot_route_entries set status='COMPLETED' where lot_id=?",lot);
        jdbc.update("update lots set status='COMPLETED',current_location_type='COMPLETED',current_location_id=null,completed_at=now(),version=version+1 where id=?",lot);
        jdbc.update("insert into lot_location_events(lot_id,location_type,actor_id) values (?,'COMPLETED',?)",lot,actor);
        jdbc.update("update styles s set status='COMPLETED',version=version+1 where s.id=(select style_id from lots where id=?) and not exists(select 1 from lots l where l.style_id=s.id and l.status not in ('COMPLETED','CANCELLED'))",lot);
    }
    public boolean isFinalQuality(UUID execution){return Boolean.TRUE.equals(jdbc.queryForObject("select p.quality and not exists(select 1 from station_visits later_sv join lot_route_entries later_lr on later_lr.id=later_sv.lot_route_entry_id join process_executions later_pe on later_pe.station_visit_id=later_sv.id where later_sv.lot_id=sv.lot_id and (later_lr.sequence_no>lr.sequence_no or (later_lr.sequence_no=lr.sequence_no and later_pe.sequence_no>pe.sequence_no))) from process_executions pe join processes p on p.id=pe.process_id join station_visits sv on sv.id=pe.station_visit_id join lot_route_entries lr on lr.id=sv.lot_route_entry_id where pe.id=?",Boolean.class,execution));}
    private boolean allowed(String from,String to,boolean supervisor){if(supervisor)return Set.of("PENDING","IN_PROGRESS","PAUSED","BLOCKED","SKIPPED","COMPLETED").contains(to);return switch(from){case"PENDING"->Set.of("IN_PROGRESS","SKIPPED").contains(to);case"IN_PROGRESS"->Set.of("PAUSED","BLOCKED","COMPLETED").contains(to);case"PAUSED"->"IN_PROGRESS".equals(to);case"BLOCKED"->Set.of("PENDING","IN_PROGRESS").contains(to);default->false;};}
    private void location(UUID lot,String type,UUID id,UUID actor){jdbc.update("insert into lot_location_events(lot_id,location_type,location_id,actor_id) values (?,?,?,?)",lot,type,id,actor);}
    private record LotRow(UUID id,String lotNumber,String status,Integer currentSequence){} private record ExecRow(String status,UUID visitId,int sequence,UUID stationId){}
}
